32	/**
33	 * 救援主流程：接报→派单→到场→施救→复检恢复→回访结案。
34	 * 接报/派单/结案以 requestId 幂等；到场满 30 分钟判超时升级；
35	 * 90 日（UTC 日界）内第 2 次困人强制停梯；复检合格与复梯同事务。
36	 */
37	@Service
38	public class RescueService {
39	
40	    /** 到场时限：接报后 30 分钟，恰满即超时 */
41	    static final long ARRIVAL_LIMIT_MINUTES = 30;
42	    /** 困人统计窗口：90 日（UTC 日界），含当日 */
43	    static final long INCIDENT_WINDOW_DAYS = 90;
44	
45	    /** 救援单行 */
46	    public record RescueRow(long id, long elevatorId, String requestId, String status,
47	                            Instant reportedAt, LocalDate reportedDay) {
48	    }
49	
50	    static final RowMapper<RescueRow> RESCUE_MAPPER = (rs, i) -> new RescueRow(
51	            rs.getLong("id"), rs.getLong("elevator_id"), rs.getString("request_id"), rs.getString("status"),
52	            rs.getObject("reported_at", LocalDateTime.class).toInstant(ZoneOffset.UTC),
53	            rs.getObject("reported_day", LocalDate.class));
54	
55	    private final JdbcTemplate jdbc;
56	    private final ElevatorService elevatorService;
57	    private final IdempotencyService idempotency;
58	    private final Clock clock;
59	
60	    public RescueService(JdbcTemplate jdbc, ElevatorService elevatorService,
61	                         IdempotencyService idempotency, Clock clock) {
62	        this.jdbc = jdbc;
63	        this.elevatorService = elevatorService;
64	        this.idempotency = idempotency;
65	        this.clock = clock;
66	    }
67	
68	    // ---------------------------------------------------------------- 接报
69	
70	    public ResponseEntity<String> report(ReportRequest req) {
71	        String fp = Fingerprints.of("scope=REPORT", "requestId=" + req.requestId(),
72	                "elevatorId=" + req.elevatorId(), "reportedAt=" + req.reportedAt());
73	        return idempotency.handle("REPORT", req.requestId(), fp, () -> doReport(req));
74	    }
75	
76	    private RescueView doReport(ReportRequest req) {
77	        ElevatorRow ev = elevatorService.lockElevator(req.elevatorId());
78	        // 并发同键重放：胜出方已提交，交由幂等记录仲裁返回首次结果
79	        List<Long> existing = jdbc.query("SELECT id FROM rescue_order WHERE request_id=?",
80	                (rs, i) -> rs.getLong(1), req.requestId());
81	        if (!existing.isEmpty()) {
82	            return view(existing.get(0));
83	        }
84	        Instant reportedAt = req.reportedAt() != null ? req.reportedAt() : Instant.now(clock);
85	        LocalDate day = reportedAt.atZone(ZoneOffset.UTC).toLocalDate();
86	        if (elevatorService.hasActiveRescue(ev.id())) {
87	            throw ApiException.conflict("ACTIVE_RESCUE_EXISTS", "同一电梯已存在进行中的救援单，唯一受理");
88	        }
89	        jdbc.update("INSERT INTO rescue_order(elevator_id, request_id, fingerprint, status, reported_at, reported_day, "
90	                        + "active_elevator_key, created_at) VALUES (?,?,?,'REPORTED',?,?,?,?)",
91	                ev.id(), req.requestId(), "report", ElevatorService.ts(reportedAt),
92	                day, ev.id(), ElevatorService.ts(Instant.now(clock)));
93	        long rescueId = jdbc.queryForObject("SELECT id FROM rescue_order WHERE request_id=?", Long.class, req.requestId());
94	        appendEvent(rescueId, "REPORTED", "接报困人", reportedAt);
95	        // 困人即停梯；已停梯（如维保锁定）则不重复落 RESCUE 停梯链
96	        elevatorService.stopIfRunning(ev, StopReason.RESCUE, rescueId, reportedAt);
97	        // 90 日（UTC 日界）内第 2 次困人：强制停梯检查
98	        LocalDate windowStart = day.minusDays(INCIDENT_WINDOW_DAYS - 1);
99	        Integer incidents = jdbc.queryForObject(
100	                "SELECT COUNT(*) FROM rescue_order WHERE elevator_id=? AND reported_day >= ?",
101	                Integer.class, ev.id(), windowStart);
102	        if (incidents != null && incidents >= 2) {
103	            boolean alreadyForced = elevatorService.openStops(ev.id()).stream()
104	                    .anyMatch(s -> StopReason.FORCE_STOP_90D.name().equals(s.reason()));
105	            if (!alreadyForced) {
106	                elevatorService.appendChain(ev.id(), ChainAction.STOP, StopReason.FORCE_STOP_90D, rescueId, reportedAt);
107	                appendEvent(rescueId, "ESCALATED", "90日内第2次困人，强制停梯检查", reportedAt);
108	            }
109	        }
110	        return view(rescueId);
111	    }
112	
113	    // ---------------------------------------------------------------- 派单
114	
115	    public ResponseEntity<String> dispatch(long rescueId, DispatchRequest req) {
116	        List<Long> sorted = req.staffIds().stream().distinct().sorted().toList();
117	        String fp = Fingerprints.of("scope=DISPATCH", "requestId=" + req.requestId(),
118	                "rescueId=" + rescueId, "staffIds=" + sorted.stream().map(String::valueOf)
119	                        .collect(Collectors.joining(",")));
120	        return idempotency.handle("DISPATCH", req.requestId(), fp, () -> doDispatch(rescueId, req.requestId(), sorted));
121	    }
122	
123	    private RescueView doDispatch(long rescueId, String requestId, List<Long> staffIds) {
124	        RescueRow r = lockRescue(rescueId);
125	        if (idempotency.exists("DISPATCH", requestId)) {
126	            // 并发同键重放：交由幂等记录仲裁返回首次结果
127	            return view(rescueId);
128	        }
129	        if (!RescueStatus.REPORTED.name().equals(r.status())) {
130	            throw ApiException.conflict("ILLEGAL_STATE", "当前状态不允许派单: " + r.status());
131	        }
132	        ElevatorRow ev = elevatorService.lockElevator(r.elevatorId());
133	        for (Long staffId : staffIds) {
134	            Integer n = jdbc.queryForObject("SELECT COUNT(*) FROM staff WHERE id=?", Integer.class, staffId);
135	            if (n == null || n == 0) {
136	                throw ApiException.notFound("人员不存在: " + staffId);
137	            }
138	        }
139	        // 停梯派单竞态的唯一终态：存在与本单无关的未闭合停梯（维保锁定等）时禁止派单
140	        boolean blocked = elevatorService.openStops(ev.id()).stream()
141	                .anyMatch(s -> s.rescueId() == null || s.rescueId() != rescueId);
142	        if (blocked) {
143	            throw ApiException.conflict("ELEVATOR_LOCKED", "电梯已停梯锁定，不得既停梯又继续派单");
144	        }
145	        Instant now = Instant.now(clock);
146	        jdbc.update("UPDATE rescue_order SET status='DISPATCHED', dispatched_at=? WHERE id=?",
147	                ElevatorService.ts(now), rescueId);
148	        for (Long staffId : staffIds) {
149	            jdbc.update("INSERT INTO rescue_staff(rescue_id, staff_id, role) VALUES (?,?,'DISPATCH')", rescueId, staffId);
150	        }
151	        appendEvent(rescueId, "DISPATCHED", "派单: " + staffIds, now);
152	        return view(rescueId);
153	    }
154	
155	    // ---------------------------------------------------------------- 到场
156	
157	    @Transactional
158	    public RescueView arrive(long rescueId, ArriveRequest req) {
159	        RescueRow r = lockRescue(rescueId);
160	        if (!RescueStatus.DISPATCHED.name().equals(r.status())) {
161	            throw ApiException.conflict("ILLEGAL_STATE", "当前状态不允许到场登记: " + r.status());
162	        }
163	        Instant arrivedAt = req.arrivedAt() != null ? req.arrivedAt() : Instant.now(clock);
164	        boolean timeout = !arrivedAt.isBefore(r.reportedAt().plus(ARRIVAL_LIMIT_MINUTES, ChronoUnit.MINUTES));
165	        jdbc.update("UPDATE rescue_order SET status='ARRIVED', arrived_at=?, timeout_escalated=?, escalated_at=? WHERE id=?",
166	                ElevatorService.ts(arrivedAt), timeout, timeout ? ElevatorService.ts(arrivedAt) : null, rescueId);
167	        appendEvent(rescueId, "ARRIVED", "到场", arrivedAt);
168	        if (timeout) {
169	            appendEvent(rescueId, "ESCALATED", "接报后满30分钟未到场，超时升级通报", arrivedAt);
170	        }
171	        return view(rescueId);
172	    }
173	
174	    // ---------------------------------------------------------------- 施救
175	
176	    @Transactional
177	    public RescueView rescue(long rescueId, RescueRequest req) {
178	        RescueRow r = lockRescue(rescueId);
179	        if (!RescueStatus.ARRIVED.name().equals(r.status())) {
180	            throw ApiException.conflict("ILLEGAL_STATE", "当前状态不允许施救登记: " + r.status());
181	        }
182	        List<Long> ids = req.staffIds().stream().distinct().sorted().toList();
183	        if (ids.size() != 2) {
184	            throw ApiException.unprocessable("TWO_RESCUERS_REQUIRED", "施救须两名持证人员，单人操作不生效");
185	        }
186	        for (Long staffId : ids) {
187	            List<Boolean> certified = jdbc.query("SELECT certified FROM staff WHERE id=?",
188	                    (rs, i) -> rs.getBoolean(1), staffId);
189	            if (certified.isEmpty()) {
190	                throw ApiException.notFound("人员不存在: " + staffId);
191	            }
192	            if (!certified.get(0)) {
193	                throw ApiException.unprocessable("UNQUALIFIED_STAFF", "施救人员未持有效证书: " + staffId);
194	            }
195	        }
196	        Instant at = req.rescuedAt() != null ? req.rescuedAt() : Instant.now(clock);
197	        jdbc.update("UPDATE rescue_order SET status='RESCUED', rescued_at=? WHERE id=?",
198	                ElevatorService.ts(at), rescueId);
199	        for (Long staffId : ids) {
200	            jdbc.update("INSERT INTO rescue_staff(rescue_id, staff_id, role) VALUES (?,?,'RESCUE')", rescueId, staffId);
201	        }
202	        appendEvent(rescueId, "RESCUED", "两名持证人员完成施救: " + ids, at);
203	        return view(rescueId);
204	    }
205	
206	    // ---------------------------------------------------------------- 复检恢复
207	
208	    @Transactional
209	    public RescueView recheck(long rescueId, RecheckRequest req) {
210	        RescueRow r = lockRescue(rescueId);
211	        if (!RescueStatus.RESCUED.name().equals(r.status())) {
212	            throw ApiException.conflict("ILLEGAL_STATE", "当前状态不允许复检: " + r.status());
213	        }
214	        if (!req.inspectionPassed()) {
215	            throw ApiException.unprocessable("INSPECTION_FAILED", "复检不合格，禁止恢复运行");
216	        }
217	        Instant at = req.recheckedAt() != null ? req.recheckedAt() : Instant.now(clock);
218	        ElevatorRow ev = elevatorService.lockElevator(r.elevatorId());
219	        jdbc.update("UPDATE rescue_order SET status='RESTORED', restored_at=? WHERE id=?",
220	                ElevatorService.ts(at), rescueId);
221	        appendEvent(rescueId, "RESTORED", "复检合格", at);
222	        // 复检合格与恢复运行同一事务：仅当未闭合停梯全部由本单引起时才复梯
223	        List<ChainRow> open = elevatorService.openStops(ev.id());
224	        boolean allMine = open.stream().allMatch(s -> s.rescueId() != null && s.rescueId() == rescueId);
225	        if (allMine) {
226	            jdbc.update("UPDATE elevator SET status='RUNNING' WHERE id=?", ev.id());
227	            elevatorService.appendChain(ev.id(), ChainAction.RESUME, StopReason.RECHECK_PASS, rescueId, at);
228	            appendEvent(rescueId, "RESUMED", "复检合格，恢复运行", at);
229	        }
230	        return view(rescueId);
231	    }
232	
233	    // ---------------------------------------------------------------- 回访结案
234	
235	    public ResponseEntity<String> close(long rescueId, CloseRequest req) {
236	        String fp = Fingerprints.of("scope=CLOSE", "requestId=" + req.requestId(),
237	                "rescueId=" + rescueId, "closedAt=" + req.closedAt());
238	        return idempotency.handle("CLOSE", req.requestId(), fp, () -> doClose(rescueId, req));
239	    }
240	
241	    private RescueView doClose(long rescueId, CloseRequest req) {
242	        RescueRow r = lockRescue(rescueId);
243	        if (RescueStatus.CLOSED.name().equals(r.status())) {
244	            // 结案为终态：重复结案返回幂等成功
245	            return view(rescueId);
246	        }
247	        if (!RescueStatus.RESTORED.name().equals(r.status())) {
248	            throw ApiException.conflict("ILLEGAL_STATE", "当前状态不允许结案: " + r.status());
249	        }
250	        Instant at = req.closedAt() != null ? req.closedAt() : Instant.now(clock);
251	        jdbc.update("UPDATE rescue_order SET status='CLOSED', closed_at=?, active_elevator_key=NULL WHERE id=?",
252	                ElevatorService.ts(at), rescueId);
253	        appendEvent(rescueId, "CLOSED", "回访结案", at);
254	        return view(rescueId);
255	    }
256	
257	    // ---------------------------------------------------------------- 查询
258	
259	    @Transactional(readOnly = true)
260	    public RescueView getRescue(long rescueId) {
261	        return view(rescueId);
262	    }
263	
264	    @Transactional(readOnly = true)
265	    public List<EventView> timeline(long rescueId) {
266	        Integer n = jdbc.queryForObject("SELECT COUNT(*) FROM rescue_order WHERE id=?", Integer.class, rescueId);
267	        if (n == null || n == 0) {
268	            throw ApiException.notFound("救援单不存在: " + rescueId);
269	        }
270	        return jdbc.query("SELECT * FROM rescue_event WHERE rescue_id=? ORDER BY id",
271	                (rs, i) -> new EventView(rs.getLong("id"), rs.getString("event"), rs.getString("detail"),
272	                        rs.getObject("created_at", LocalDateTime.class).toInstant(ZoneOffset.UTC)),
273	                rescueId);
274	    }
275	
276	    // ---------------------------------------------------------------- 内部
277	
278	    private RescueRow lockRescue(long rescueId) {
279	        List<RescueRow> rows = jdbc.query("SELECT * FROM rescue_order WHERE id=? FOR UPDATE", RESCUE_MAPPER, rescueId);
280	        if (rows.isEmpty()) {
281	            throw ApiException.notFound("救援单不存在: " + rescueId);
282	        }
283	        return rows.get(0);
284	    }
285	
286	    private RescueView view(long rescueId) {
287	        return jdbc.queryForObject(
288	                "SELECT * FROM rescue_order WHERE id=?",
289	                (rs, i) -> new RescueView(rs.getLong("id"), rs.getLong("elevator_id"), rs.getString("request_id"),
290	                        rs.getString("status"), toInstant(rs, "reported_at"), toInstant(rs, "dispatched_at"),
291	                        toInstant(rs, "arrived_at"), toInstant(rs, "rescued_at"), toInstant(rs, "restored_at"),
292	                        toInstant(rs, "closed_at"), rs.getBoolean("timeout_escalated"),
293	                        toInstant(rs, "escalated_at")),
294	                rescueId);
295	    }
296	
297	    private static Instant toInstant(java.sql.ResultSet rs, String col) throws java.sql.SQLException {
298	        LocalDateTime v = rs.getObject(col, LocalDateTime.class);
299	        return v == null ? null : v.toInstant(ZoneOffset.UTC);
300	    }
301	
302	    private void appendEvent(long rescueId, String event, String detail, Instant at) {
303	        jdbc.update("INSERT INTO rescue_event(rescue_id, event, detail, created_at) VALUES (?,?,?,?)",
304	                rescueId, event, detail, ElevatorService.ts(at));
305	    }
306	}
