47	
48	    @Test
49	    @DisplayName("施救须两名持证人员：单人或含未持证人员均不生效")
50	    void rescueRequiresTwoCertifiedStaff() throws Exception {
51	        long e1 = createElevator("T2P-A", LocalDate.of(2026, 1, 1));
52	        long s1 = createStaff("C-2P-1", true);
53	        long s2 = createStaff("C-2P-2", true);
54	        long s3 = createStaff("C-2P-3", false);
55	
56	        long r1 = report("T2P-r1", e1, T0).id();
57	        assertEquals(200, dispatch("T2P-d1", r1, List.of(s1)).status());
58	        assertEquals(200, arrive(r1, T0.plusSeconds(600)).status());
59	
60	        Resp single = rescue(r1, List.of(s1));
61	        assertEquals(422, single.status(), "单人施救不生效");
62	        assertEquals("TWO_RESCUERS_REQUIRED", single.text("error"));
63	
64	        Resp uncertified = rescue(r1, List.of(s1, s3));
65	        assertEquals(422, uncertified.status(), "含未持证人员不生效");
66	        assertEquals("UNQUALIFIED_STAFF", uncertified.text("error"));
67	
68	        Resp ok = rescue(r1, List.of(s1, s2));
69	        assertEquals(200, ok.status());
70	        assertEquals("RESCUED", ok.text("status"));
71	    }
72	
73	    @Test
74	    @DisplayName("90日（UTC日界）内恰第2次困人强制停梯；第90日之外不触发")
75	    void secondIncidentWithin90DaysForcesStop() throws Exception {
76	        long s1 = createStaff("C-90-1", true);
77	        long s2 = createStaff("C-90-2", true);
78	
79	        // 窗口内：第 1 次 2026-03-01，第 2 次 2026-05-29（相隔 89 个 UTC 日）
80	        long e1 = createElevator("T90-A", LocalDate.of(2026, 1, 1));
81	        fullLifecycle(e1, s1, s2, "T90-first", Instant.parse("2026-03-01T08:00:00Z"));
82	        assertEquals("RUNNING", elevator(e1).text("status"), "首单复检后应恢复运行");
83	
84	        Resp second = report("T90-second", e1, Instant.parse("2026-05-29T08:00:00Z"));
85	        assertEquals(200, second.status());
86	        assertEquals("STOPPED", elevator(e1).text("status"));
87	        assertTrue(chainHas(e1, "STOP", "FORCE_STOP_90D"), "恰第2次困人应强制停梯检查");
88	        assertTrue(timelineHas(second.id(), "ESCALATED"));
89	
90	        // 窗口外：第 2 次在 2026-05-30（相隔 90 个 UTC 日），不触发强制停梯
91	        long e2 = createElevator("T90-B", LocalDate.of(2026, 1, 1));
92	        fullLifecycle(e2, s1, s2, "T90-out1", Instant.parse("2026-03-01T08:00:00Z"));
93	        Resp outside = report("T90-out2", e2, Instant.parse("2026-05-30T08:00:00Z"));
