    long id = jdbc.queryForObject("SELECT MAX(id) FROM maintenance_record WHERE elevator_id=?",
            Long.class, elevatorId);
    return jdbc.queryForObject("SELECT * FROM maintenance_record WHERE id=?", this::mapView, id);
}

