        assertEquals("ATTEMPT", obligation(ob).text("settledBy"));
        assertEquals("2026-01-15", elevator(e1).text("lastMaintenanceDay"));
        assertEquals("RUNNING", elevator(e1).text("status"));

        Integer compliant = jdbc.queryForObject(
